import{_ as i}from"./chunks/Audio.COine8Wh.js";import{c as o,o as s,j as t,G as a,ae as l,a as n}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"SAVING COLLEGE SPORTS","description":"","frontmatter":{"legisId":"2025-07-24-saving-college-sports","title":"SAVING COLLEGE SPORTS","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/07/saving-college-sports/","publishDate":"2025-07-24T16:39:36-04:00","head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Executive Orders\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"SAVING COLLEGE SPORTS\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders/2025-07-24-saving-college-sports\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"SAVING COLLEGE SPORTS\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/executive-orders/2025-07-24-saving-college-sports\\",\\"datePublished\\":\\"2025-07-24T16:39:36-04:00\\",\\"dateModified\\":1782442092000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/executive-orders/2025-07-24-saving-college-sports\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"executive-orders/2025-07-24-saving-college-sports.md","filePath":"executive-orders/2025-07-24-saving-college-sports.md","lastUpdated":1782442092000}'),r={name:"executive-orders/2025-07-24-saving-college-sports.md"},h=Object.assign(r,{setup(p){return(c,e)=>(s(),o("div",null,[e[0]||(e[0]=t("h1",{id:"saving-college-sports",tabindex:"-1"},[n("SAVING COLLEGE SPORTS "),t("a",{class:"header-anchor",href:"#saving-college-sports","aria-label":'Permalink to "SAVING COLLEGE SPORTS"'},"​")],-1)),a(i),e[1]||(e[1]=l('<p>Published on Thursday, July 24, 2025</p><ul><li><p><strong>Overview of College Sports</strong></p><ul><li>College sports provide significant educational and leadership opportunities for over 500,000 student-athletes, with nearly $4 billion in scholarships annually.</li><li>They contribute to local economies and cultural activities in many communities.</li><li>Major college football and athletics lead to high international success, particularly in the Olympics, where a significant portion of Olympic athletes are former collegiate athletes.</li></ul></li><li><p><strong>Current Challenges Faced</strong></p><ul><li>There is an unprecedented threat to the future of college sports due to litigation against athlete compensation rules.</li><li>Recent court rulings have eliminated restrictions on athlete compensation and transfers, resulting in bidding wars among universities for top players.</li><li>This creates an imbalanced system where financial resources are disproportionately directed towards revenue-generating sports, threatening non-revenue sports.</li></ul></li><li><p><strong>Urgent Need for National Solutions</strong></p><ul><li>A national framework is necessary to protect and preserve college sports and non-revenue programs.</li><li>Colleges have begun directly paying athletes but need to simultaneously strengthen non-revenue sports.</li><li>Immediate action is needed to enforce reasonable limits on athlete compensation and to ensure fair distribution of resources.</li></ul></li><li><p><strong>Executive Branch Policies</strong></p><ul><li>Preservation and potential expansion of scholarship opportunities in women’s and non-revenue sports for the 2025-2026 season and beyond.</li><li>Colleges earning over $125 million must increase scholarships and roster spots for non-revenue sports; those with over $50 million must maintain scholarship levels.</li><li>Revenue-sharing between universities and athletes should not compromise opportunities in women’s and non-revenue sports.</li><li>Prohibition of third-party, pay-for-play payments, while allowing fair market value compensation for endorsements.</li></ul></li><li><p><strong>Implementation Steps</strong></p><ul><li>The Secretary of Education will work with relevant agencies to develop a plan to promote these policies within 30 days.</li><li>The Secretary of Labor and National Labor Relations Board will clarify the status of collegiate athletes for maximizing benefits in education and athletics.</li><li>The Attorney General and FTC Chairman will stabilize college athletics through legal measures and develop guidelines for protecting student-athletes&#39; rights within 60 days.</li></ul></li><li><p><strong>Collaboration with Athlete Organizations</strong></p><ul><li>Consultation with the U.S. Olympic and Paralympic Committee to safeguard the role of collegiate athletics in developing athletes for international competitions.</li></ul></li><li><p><strong>Legal and Administrative Notes</strong></p><ul><li>The order does not affect existing legal authorities or create enforceable rights against the U.S. government.</li><li>Implementation is subject to applicable law and budget appropriations.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/07/saving-college-sports/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/07/saving-college-sports/</a></p>',3))]))}});export{u as __pageData,h as default};
